"""Runtime settings read from the environment (never committed; see .env.example)."""
from __future__ import annotations

import os
import secrets
from dataclasses import dataclass, field
from pathlib import Path

DEFAULT_APP_DB = Path(__file__).resolve().parents[2] / "data" / "app.db"
SESSION_TTL_SECONDS = 7 * 24 * 3600


@dataclass
class Settings:
    app_db: Path = DEFAULT_APP_DB
    dev_user: str = ""
    dev_password: str = ""
    cookie_secure: bool = False
    session_secret: bytes = field(default_factory=lambda: secrets.token_bytes(32))
    nonce_secret: bytes | None = None
    google_client_id: str | None = None
    ping_interval: float = 2.0  # /api/debug/sse-ping spacing, seconds

    @property
    def dev_login(self) -> bool:
        return bool(self.dev_user and self.dev_password)

    @classmethod
    def from_env(cls, env=None) -> "Settings":
        env = os.environ if env is None else env
        s = cls()
        if env.get("APP_DB"):
            s.app_db = Path(env["APP_DB"])
        s.dev_user = env.get("DEV_AUTH_USER", "")
        s.dev_password = env.get("DEV_AUTH_PASSWORD", "")
        s.cookie_secure = env.get("COOKIE_SECURE", "").strip().lower() in ("1", "true", "yes", "on")
        # Without SESSION_SECRET a restart signs everyone out (random key per process).
        if env.get("SESSION_SECRET"):
            s.session_secret = env["SESSION_SECRET"].encode()
        if env.get("NONCE_SECRET"):
            s.nonce_secret = env["NONCE_SECRET"].encode()
        s.google_client_id = env.get("GOOGLE_CLIENT_ID") or None
        return s
"""Stateless signed session cookie: `<user_id>.<expires>.<hmac>`. Logout clears the cookie."""
from __future__ import annotations

import hashlib
import hmac
import time

COOKIE = "oa_session"


def _sig(secret: bytes, payload: str) -> str:
    return hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()[:40]


def issue(secret: bytes, user_id: str, ttl: int, now: float | None = None) -> str:
    payload = f"{user_id}.{int((time.time() if now is None else now) + ttl)}"
    return f"{payload}.{_sig(secret, payload)}"


def verify(secret: bytes, value: str | None, now: float | None = None) -> str | None:
    """The user id in a valid, unexpired cookie, else None."""
    if not value or value.count(".") != 2:
        return None
    user_id, expires, sig = value.split(".")
    if not hmac.compare_digest(sig, _sig(secret, f"{user_id}.{expires}")):
        return None
    if not expires.isdigit() or int(expires) <= (time.time() if now is None else now):
        return None
    return user_id
"""Error bodies: HTTP status + {"error": {"code", "message"}} for every failure."""
from __future__ import annotations

from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

from ..airline import BookingError, NotFound
from ..core.network import NetworkDataError


class ApiError(Exception):
    def __init__(self, status: int, code: str, message: str):
        self.status, self.code, self.message = status, code, message


def body(code: str, message: str) -> dict:
    return {"error": {"code": code, "message": message}}


def respond(status: int, code: str, message: str) -> JSONResponse:
    return JSONResponse(body(code, message), status_code=status)


_BY_STATUS = {401: "unauthorized", 404: "not_found", 405: "method_not_allowed", 429: "rate_limited"}


def install_handlers(app: FastAPI) -> None:
    @app.exception_handler(ApiError)
    async def _api(_: Request, e: ApiError):
        return respond(e.status, e.code, e.message)

    @app.exception_handler(NotFound)
    async def _not_found(_: Request, e: NotFound):
        return respond(404, "not_found", "Not found.")

    @app.exception_handler(BookingError)
    async def _booking(_: Request, e: BookingError):
        return JSONResponse(e.as_response(), status_code=e.status)

    @app.exception_handler(NetworkDataError)
    async def _data(_: Request, e: NetworkDataError):
        return respond(503, "data_unavailable", "Route data could not be read right now. Please try again.")

    @app.exception_handler(RequestValidationError)
    async def _validation(_: Request, e: RequestValidationError):
        return respond(400, "bad_request", "The request body is not valid.")

    @app.exception_handler(StarletteHTTPException)
    async def _http(_: Request, e: StarletteHTTPException):
        code = _BY_STATUS.get(e.status_code, "bad_request" if e.status_code < 500 else "internal_error")
        return respond(e.status_code, code, "Not found." if e.status_code == 404 else str(e.detail))
